import{_ as t,o as a,c as n,a0 as s}from"./chunks/framework.BxrwG5q5.js";const p=JSON.parse('{"title":"Targeting Rules","description":"","frontmatter":{},"headers":[],"relativePath":"features/targeting.md","filePath":"features/targeting.md"}'),r={name:"features/targeting.md"};function i(o,e,l,u,d,g){return a(),n("div",null,[...e[0]||(e[0]=[s(`<h1 id="targeting-rules" tabindex="-1">Targeting Rules <a class="header-anchor" href="#targeting-rules" aria-label="Permalink to &quot;Targeting Rules&quot;">​</a></h1><blockquote><p>See also: <a href="/config/features/segments.html">Segments</a> · <a href="/config/features/rollouts.html">Percentage Rollouts</a> · <a href="/config/guide/scopes.html">Configuration Scopes</a></p></blockquote><p>Targeting rules are the core mechanism for <strong>user segmentation</strong> — serving different config values to different users based on their attributes or <a href="/config/features/segments.html">segment</a> membership. They power <strong>A/B testing</strong>, <strong>multivariate testing</strong>, <strong>feature gating</strong>, and <strong>personalization</strong>.</p><p>Rules are evaluated in <strong>priority order</strong> (lowest number first). The first match wins. If no rules match, the default value is returned.</p><h2 id="a-b-testing-and-multivariate-testing" tabindex="-1">A/B Testing and Multivariate Testing <a class="header-anchor" href="#a-b-testing-and-multivariate-testing" aria-label="Permalink to &quot;A/B Testing and Multivariate Testing&quot;">​</a></h2><p>A boolean flag with two targeting rules — one returning <code>true</code> for a treatment segment, one returning <code>false</code> as default — is a standard <strong>A/B test</strong>. Each targeting rule is a variant arm.</p><p>For <strong>multivariate tests (MVT)</strong>, use a string or JSON flag with one rule per variant:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Priority 1: If user in &quot;Variant B&quot; segment → value: &quot;redesign_v2&quot;</span></span>
<span class="line"><span>Priority 2: If user in &quot;Variant C&quot; segment → value: &quot;redesign_v3&quot;</span></span>
<span class="line"><span>Default: &quot;original&quot;</span></span></code></pre></div><p>Each user is consistently in one variant because <a href="/config/features/segments.html">segment membership is evaluated server-side</a> against a stable userId.</p><h2 id="two-types-of-rules" tabindex="-1">Two Types of Rules <a class="header-anchor" href="#two-types-of-rules" aria-label="Permalink to &quot;Two Types of Rules&quot;">​</a></h2><h3 id="_1-segment-based-rules-recommended" tabindex="-1">1. Segment-Based Rules (Recommended) <a class="header-anchor" href="#_1-segment-based-rules-recommended" aria-label="Permalink to &quot;1. Segment-Based Rules (Recommended)&quot;">​</a></h3><p>The simplest targeting pattern. Pick segments, assign a value. Ideal for <strong>cohort targeting</strong> — feature gating by plan, beta group, geography, etc.</p><ul><li>Click <strong>Target Segment</strong></li><li>Select one or more segments (OR logic — user in ANY gets the value)</li><li>Set the return value</li></ul><h3 id="_2-condition-based-rules-advanced" tabindex="-1">2. Condition-Based Rules (Advanced) <a class="header-anchor" href="#_2-condition-based-rules-advanced" aria-label="Permalink to &quot;2. Condition-Based Rules (Advanced)&quot;">​</a></h3><p>Inline attribute conditions without creating a named segment. Use when the condition is flag-specific and not worth reusing.</p><ul><li>Click <strong>Custom Condition</strong></li><li>Define conditions: <code>attribute</code> <code>operator</code> <code>value</code></li><li>AND conditions within a group, OR groups for alternatives</li></ul><h2 id="feature-gating" tabindex="-1">Feature Gating <a class="header-anchor" href="#feature-gating" aria-label="Permalink to &quot;Feature Gating&quot;">​</a></h2><p>Returning a specific value only for users who meet a condition — &quot;this feature is only available to Enterprise plan users&quot; — is called <strong>feature gating</strong>. It&#39;s a targeting rule where the gate condition is the plan, role, or entitlement attribute.</p><p>See <a href="/config/features/prerequisites.html">Prerequisites</a> for <strong>dependency-based feature gating</strong> — gating one flag on the state of another.</p><h2 id="value-type-validation" tabindex="-1">Value Type Validation <a class="header-anchor" href="#value-type-validation" aria-label="Permalink to &quot;Value Type Validation&quot;">​</a></h2><p>The return value is validated against the config&#39;s type — you can&#39;t type &quot;hello&quot; as a value for a boolean flag.</p><table tabindex="0"><thead><tr><th>Config Type</th><th>Input</th></tr></thead><tbody><tr><td>Boolean</td><td><code>true</code>/<code>false</code> toggle</td></tr><tr><td>Number</td><td>Numeric input only</td></tr><tr><td>String</td><td>Free text</td></tr><tr><td>JSON</td><td>Monospace JSON input</td></tr></tbody></table><h2 id="evaluation-order" tabindex="-1">Evaluation Order <a class="header-anchor" href="#evaluation-order" aria-label="Permalink to &quot;Evaluation Order&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>1. Archived       — return undefined</span></span>
<span class="line"><span>2. Prerequisites  — if unmet, return default</span></span>
<span class="line"><span>3. Overrides      — user-specific force targeting</span></span>
<span class="line"><span>4. Schedule       — time-gated value</span></span>
<span class="line"><span>5. Targeting Rules — evaluated here, priority order</span></span>
<span class="line"><span>6. Rollout        — canary percentage</span></span>
<span class="line"><span>7. Default        — base value</span></span></code></pre></div><h2 id="server-side-vs-client-side-evaluation" tabindex="-1">Server-Side vs Client-Side Evaluation <a class="header-anchor" href="#server-side-vs-client-side-evaluation" aria-label="Permalink to &quot;Server-Side vs Client-Side Evaluation&quot;">​</a></h2><ul><li><strong>Client keys (<code>cid_</code>):</strong> Targeting is evaluated server-side. Rules and segment conditions never reach the browser — no data leakage risk.</li><li><strong>Server keys (<code>svr_</code>):</strong> Full rules returned; the SDK evaluates locally via plugins. Useful for latency-sensitive scenarios.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/config/features/segments.html">Segments</a> — Reusable audience groups for targeting rules</li><li><a href="/config/features/rollouts.html">Percentage Rollouts</a> — Canary delivery after targeting is evaluated</li><li><a href="/config/features/prerequisites.html">Prerequisites</a> — Dependency-based feature gating</li><li><a href="/config/features/scheduling.html">Scheduling</a> — Time-based targeting above the rule evaluation step</li><li><a href="/config/guide/scopes.html">Configuration Scopes</a> — Full evaluation pipeline and context model</li></ul>`,28)])])}const h=t(r,[["render",i]]);export{p as __pageData,h as default};
